import React, { useState } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:8000/api';

const DownloadForm = ({ setDownloadStatus }) => {
  const [url, setUrl] = useState('');
  const [mediaType, setMediaType] = useState('video');
  const [videoQuality, setVideoQuality] = useState('720p');
  const [videoFormat, setVideoFormat] = useState('mp4');
  const [audioQuality, setAudioQuality] = useState('128k');
  const [audioFormat, setAudioFormat] = useState('mp3');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [formats, setFormats] = useState(null);
  
  const handleUrlChange = (e) => {
    setUrl(e.target.value);
    setFormats(null); // Reset formats when URL changes
  };
  
  const fetchFormats = async (e) => {
    e.preventDefault();
    if (!url) return;
    
    setLoading(true);
    setError(null);
    
    try {
      const response = await axios.post(`${API_URL}/formats`, { url });
      setFormats(response.data);
    } catch (err) {
      setError(`Failed to get formats: ${err.response?.data?.detail || err.message}`);
    } finally {
      setLoading(false);
    }
  };
  
  const startDownload = async (e) => {
    e.preventDefault();
    if (!url) return;
    
    setLoading(true);
    setError(null);
    
    try {
      const quality = mediaType === 'video' ? videoQuality : audioQuality;
      const fileFormat = mediaType === 'video' ? videoFormat : audioFormat;
      
      const response = await axios.post(`${API_URL}/download`, {
        url,
        format_type: mediaType,
        quality,
        file_format: fileFormat
      });
      
      const taskId = response.data.task_id;
      
      // Start polling for progress
      setDownloadStatus({
        taskId,
        status: 'queued',
        progress: 0
      });
      
      const pollInterval = setInterval(async () => {
        try {
          const progressResponse = await axios.get(`${API_URL}/progress/${taskId}`);
          const { status, progress, error } = progressResponse.data;
          
          setDownloadStatus({ taskId, status, progress, error });
          
          if (status === 'completed') {
            clearInterval(pollInterval);
            // Create download link
            window.location.href = `${API_URL}/download/${taskId}`;
          } else if (status === 'error') {
            clearInterval(pollInterval);
            setError(`Download failed: ${error}`);
          }
        } catch (err) {
          clearInterval(pollInterval);
          setError(`Failed to get progress: ${err.message}`);
        }
      }, 1000);
      
    } catch (err) {
      setError(`Failed to start download: ${err.response?.data?.detail || err.message}`);
    } finally {
      setLoading(false);
    }
  };
  
  return (
    <div className="download-form">
      <form onSubmit={fetchFormats}>
        <div className="mb-3">
          <label htmlFor="url" className="form-label">Video/Audio URL</label>
          <div className="input-group">
            <input
              type="text"
              className="form-control"
              id="url"
              value={url}
              onChange={handleUrlChange}
              placeholder="Paste YouTube, Facebook, Instagram, or TikTok URL"
              required
            />
            <button 
              type="submit" 
              className="btn btn-outline-primary"
              disabled={loading || !url}
            >
              {loading ? 'Loading...' : 'Check Formats'}
            </button>
          </div>
        </div>
      </form>
      
      {error && (
        <div className="alert alert-danger">{error}</div>
      )}
      
      {formats && (
        <form onSubmit={startDownload}>
          <div className="mb-3">
            <label className="form-label">Media Type</label>
            <div className="btn-group d-flex" role="group">
              <input
                type="radio"
                className="btn-check"
                name="mediaType"
                id="videoType"
                value="video"
                checked={mediaType === 'video'}
                onChange={() => setMediaType('video')}
              />
              <label className="btn btn-outline-primary" htmlFor="videoType">Video</label>
              
              <input
                type="radio"
                className="btn-check"
                name="mediaType"
                id="audioType"
                value="audio"
                checked={mediaType === 'audio'}
                onChange={() => setMediaType('audio')}
              />
              <label className="btn btn-outline-primary" htmlFor="audioType">Audio Only</label>
            </div>
          </div>
          
          {mediaType === 'video' ? (
            <div className="row mb-3">
              <div className="col-md-6">
                <label htmlFor="videoQuality" className="form-label">Video Quality</label>
                <select
                  className="form-select"
                  id="videoQuality"
                  value={videoQuality}
                  onChange={(e) => setVideoQuality(e.target.value)}
                >
                  <option value="480p">480p</option>
                  <option value="720p">720p</option>
                  <option value="1080p">1080p</option>
                  <option value="4K">4K (2160p)</option>
                </select>
              </div>
              <div className="col-md-6">
                <label htmlFor="videoFormat" className="form-label">Format</label>
                <select
                  className="form-select"
                  id="videoFormat"
                  value={videoFormat}
                  onChange={(e) => setVideoFormat(e.target.value)}
                >
                  <option value="mp4">MP4</option>
                  <option value="webm">WebM</option>
                </select>
              </div>
            </div>
          ) : (
            <div className="row mb-3">
              <div className="col-md-6">
                <label htmlFor="audioQuality" className="form-label">Audio Quality</label>
                <select
                  className="form-select"
                  id="audioQuality"
                  value={audioQuality}
                  onChange={(e) => setAudioQuality(e.target.value)}
                >
                  <option value="128k">128 kbps</option>
                  <option value="256k">256 kbps</option>
                  <option value="320k">320 kbps</option>
                </select>
              </div>
              <div className="col-md-6">
                <label htmlFor="audioFormat" className="form-label">Format</label>
                <select
                  className="form-select"
                  id="audioFormat"
                  value={audioFormat}
                  onChange={(e) => setAudioFormat(e.target.value)}
                >
                  <option value="mp3">MP3</option>
                  <option value="m4a">M4A</option>
                  <option value="opus">Opus</option>
                </select>
              </div>
            </div>
          )}
          
          <div className="d-grid gap-2">
            <button 
              type="submit" 
              className="btn btn-primary"
              disabled={loading}
            >
              {loading ? 'Processing...' : 'Download'}
            </button>
          </div>
        </form>
      )}
    </div>
  );
};

export default DownloadForm;
